  ["about_freekill_description"] = "<b>About FreeKill</b><br/>FreeKill is an open-source Bang!-like board game, which is aim to be extensive.<br/><br/>Repo: https://github.com/Notify-ctrl/FreeKill",
  ["about_git2_description"] = "<b>About Libgit2</b><br/>Libgit2 is a lightweight, cross-platform, pure-C library that supports most of Git’s core operations and binds to almost any language that can call C.<br/><br/>FreeKill uses libgit2’s C API, and uses Git itself to download, update and manage extension packages.<br/><br/>Website: https://libgit2.org",
  ["about_gplv3_description"] = "<b>About GPLv3</b><br/>The GNU General Public License (GPL) is a widely used free-software licence that guarantees users the freedom to run, study, share and modify the software.<br/><br/>Qt is released under GPLv3, the readline library this program uses is GPLv3 as well, and QSanguosha — from which a good deal of code and thinking was borrowed — is also GPLv3, so this project is released under GPLv3 too.<br/><br/>Website: https://gplv3.fsf.org",
  ["about_lua_description"] = "<b>About Lua</b><br/>Lua is a small, flexible, efficient scripting language, widely used in game development.<br/><br/>This program uses Lua 5.4, and the whole of the game logic is implemented in it.<br/><br/>Website: https://www.lua.org",
  ["about_ossl_description"] = "<b>About OpenSSL</b><br/>OpenSSL is an open-source package providing secure communication and a wide range of cryptography.<br/><br/>This program currently uses the crypto library, for RSA support.<br/><br/>Website: https://www.openssl.org",
  ["about_qt_description"] = "<b>About Qt</b><br/>Qt is a C++ framework for building graphical applications, with strong cross-platform support and an easy-to-use API.<br/><br/>This program uses Qt 6.2+: the UI is built mainly with QtQuick, and the server uses Qt’s networking library.<br/><br/>Website: https://www.qt.io",
  ["about_sqlite_description"] = "<b>About SQLite</b><br/>SQLite is a lightweight database: cheap on resources, fast, and easy to embed.<br/><br/>FreeKill uses sqlite3 to store all user information on the server.<br/><br/>Website: https://www.sqlite.org",
